{{/* @dot github.com/donseba/go-webthings/modules/directory.ListView */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    <h1>{{.Title}}</h1>
    {{with .URL}}<a href="{{.}}">URL</a>{{end}}
    {{with .Query}}<p>{{.}}</p>{{end}}
    {{with .Category}}
        <section>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{with .Slug}}<p>{{.}}</p>{{end}}
            {{with .Summary}}<p>{{.}}</p>{{end}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            <p>Count: {{.Count}}</p>
            {{if .Active}}<p>Active</p>{{end}}
        </section>
    {{end}}
    {{range .Categories}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{with .Slug}}<p>{{.}}</p>{{end}}
            {{with .Summary}}<p>{{.}}</p>{{end}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            <p>Count: {{.Count}}</p>
            {{if .Active}}<p>Active</p>{{end}}
        </article>
    {{end}}
    {{range .Groups}}
        <article>
            {{with .Category}}
                <section>
                </section>
            {{end}}
            {{range .Entries}}
                <article>
                </article>
            {{end}}
        </article>
    {{end}}
    <p>Count: {{.Count}}</p>
</main>

