Types.Decl:
type APIAddress struct {
	Street   string `json:"street"`
	Postcode string `json:"postcode"`
	City     string `json:"city"`
}

type APICategory struct {
	ID      string `json:"id"`
	Slug    string `json:"slug"`
	Name    string `json:"name"`
	Summary string `json:"summary"`
	// EntryCount is the number of published entries in the category.
	EntryCount int `json:"entry_count"`
	// URL is the category's page, null while the directory is on no page;
	// EntriesURL its entries in the API.
	URL        *string `json:"url"`
	EntriesURL string  `json:"entries_url"`
}

type APIDay struct {
	Day   string  `json:"day"`
	Open  *string `json:"open"`
	Close *string `json:"close"`
}

type APIEntry struct {
	ID       string   `json:"id"`
	Slug     string   `json:"slug"`
	Name     string   `json:"name"`
	Summary  string   `json:"summary"`
	Keywords []string `json:"keywords"`
	// DescriptionHTML is the entry's description as HTML (api.HTML); only
	// the entry's own endpoint has it.
	DescriptionHTML string      `json:"description_html,omitempty"`
	Category        APICategory `json:"category"`
	Image           *api.Image  `json:"image"`
	Website         *string     `json:"website"`
	Email           *string     `json:"email"`
	Phone           *string     `json:"phone"`
	Address         *APIAddress `json:"address"`
	Location        *APIPoint   `json:"location"`
	// OpeningHours are the days from Monday to Sunday, null for an entry
	// without opening hours; HoursNote is the editors' note about them.
	OpeningHours []APIDay `json:"opening_hours"`
	HoursNote    string   `json:"hours_note"`
	// URL is the entry's page, null while the directory is on no page;
	// APIURL the entry in the API.
	URL       *string   `json:"url"`
	APIURL    string    `json:"api_url"`
	UpdatedAt time.Time `json:"updated_at"`
}

type APIPoint struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Category struct {
	ID      string
	Name    string
	Slug    string
	Summary string
	URL     string
	// Count is the number of published entries in the category.
	Count int
	// Active is set on the category the list is filtered by.
	Active bool
}

type CategoryFields struct {
	Slug string `db:"slug"`
}

type CategoryText struct {
	Name    string `db:"name"`
	Summary string `db:"summary"`
}

type CategoryView struct {
	Category Category
	Entries  []Entry
	// ListURL links back to the whole directory.
	ListURL string
}

type Day struct {
	Open  string `json:"open,omitempty"`
	Close string `json:"close,omitempty"`
}

type EntryText struct {
	Summary     string `db:"summary"`
	Description string `db:"description"`
	Keywords    string `db:"keywords"`
	HoursNote   string `db:"hours_note"`
}

type Group struct {
	Category Category
	Entries  []Entry
}

type ImportOptions struct {
	// Locale is the language of the summary, keywords and new category names.
	Locale string
	// Update changes entries whose slug already exists; otherwise such rows
	// are skipped.
	Update bool
	// Publish publishes the entries and categories the import creates.
	// Existing categories keep their state: an editor may hide a category on
	// purpose, so entries imported into an unpublished category stay off the
	// site until the category is published.
	Publish bool
}

type ImportProblem struct {
	Row    int
	Reason string
}

type ListView struct {
	// Title is the title of the page the module is mounted on.
	Title string
	// URL is the list's address, the action of a search form.
	URL string
	// Query is the search (?q=); empty shows every entry.
	Query string
	// Category is set when the list is filtered (?category=).
	Category *Category
	// Categories are all categories with entries, for a filter menu.
	Categories []Category
	// Groups hold the matching entries per category, in category order.
	Groups []Group
	// Count is the number of matching entries.
	Count int
}

type Query struct {
	// Search holds words that must all appear in the name, summary or
	// keywords. Case and accents are ignored, as in the site search.
	Search string
	// Category is a category slug.
	Category string
}

type Service struct {
	// contains unexported fields
}

type WeekDay struct {
	Weekday time.Weekday
	Day
}
